// 1-2. Clarify+example: array + target; return indices. [2,7,11], t=9 -> [0,1]
// 3. Brute force: check every pair -> O(n^2). State this aloud.
// 4. Optimize: a HashMap of value->index gives O(n). Pattern = complement lookup.
int[] twoSum(int[] nums, int target) {
    Map<Integer,Integer> seen = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int need = target - nums[i];
        if (seen.containsKey(need)) return new int[]{seen.get(need), i};
        seen.put(nums[i], i);
    }
    return new int[]{-1, -1};   // 6. test: no-pair case
}
// 7. Analyze: O(n) time, O(n) space.
