// Signal: "sorted array, find two numbers that sum to target"
// -> SORTED + PAIR => two pointers, O(n), O(1) space
int[] twoSumSorted(int[] a, int target) {
    int lo = 0, hi = a.length - 1;
    while (lo < hi) {
        int sum = a[lo] + a[hi];
        if (sum == target) return new int[]{lo, hi};
        if (sum < target) lo++;     // need bigger -> move left pointer right
        else hi--;                  // need smaller -> move right pointer left
    }
    return new int[]{-1, -1};
}
// If the array were UNSORTED, the signal would point to HASHING instead.
