// Stuck on 'max subarray sum'? Hand-trace tiny inputs out loud:
// [5]        -> 5
// [-2, 5]    -> 5  (drop the negative prefix)
// [5, -2, 3] -> 6  (running sum resets when it goes negative)
// Pattern spotted -> Kadane's running maximum:
int maxSubArray(int[] a) {
    int best = a[0], cur = a[0];
    for (int i = 1; i < a.length; i++) {
        cur = Math.max(a[i], cur + a[i]);   // reset or extend
        best = Math.max(best, cur);
    }
    return best;   // O(n) time, O(1) space
}
