int maxOf(int[] a) {
    if (a == null || a.length == 0)            // null + empty
        throw new IllegalArgumentException("empty");
    int max = a[0];                            // single element is safe
    for (int i = 1; i < a.length; i++)         // i<length: no off-by-one
        max = Math.max(max, a[i]);
    return max;
}

