// Find if any two numbers sum to target - nested loops
boolean hasPair(int[] a, int target) {
    for (int i = 0; i < a.length; i++)
        for (int j = i + 1; j < a.length; j++)   // O(n^2) - the bottleneck
            if (a[i] + a[j] == target) return true;
    return false;
}
