// Trade O(n) space for O(n) time: remember what we've seen
boolean hasPair(int[] a, int target) {
    Set<Integer> seen = new HashSet<>();
    for (int x : a) {
        if (seen.contains(target - x)) return true;  // O(1) lookup
        seen.add(x);
    }
    return false;
}
// New complexity: O(n) time, O(n) space. Tradeoff: extra memory for speed.
